<style>
.create-premium{color:var(--text-primary)}.create-progress{display:flex;align-items:center;gap:10px;margin-bottom:14px;font-size:11px;font-weight:600;color:var(--text-faint)}.create-progress .active{color:var(--accent)}.create-progress .step-dot{display:inline-grid;place-items:center;width:20px;height:20px;border:1px solid var(--border-glass);border-radius:50%;margin-right:5px}.create-progress .active .step-dot{background:var(--accent);color:#fff;border-color:var(--accent)}.create-progress .progress-line{width:30px;height:1px;background:var(--border-glass)}.create-premium h1{letter-spacing:-.035em}.create-premium .cl-card{border:0;background:transparent;padding:0}.create-premium .cl-primary-grid{gap:16px}.create-premium .cl-primary{position:relative;padding:22px;border-radius:18px;background:var(--bg-card);border-color:var(--border-glass);gap:6px;overflow:hidden;min-height:192px}.create-premium .cl-primary strong{margin-top:10px;font-size:17px;letter-spacing:-.02em}.create-art{display:block;width:112px;height:70px;color:var(--text-dimmed)}.create-art svg{width:100%;height:100%;overflow:visible}.create-art .art-surface{fill:var(--bg-card)}.create-art .art-tint{fill:currentColor;opacity:.08}.create-art .art-line{stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.create-art .art-solid{fill:currentColor}.create-check{position:absolute;right:18px;top:18px;display:grid;place-items:center;width:21px;height:21px;border-radius:50%;background:var(--accent);color:#fff;opacity:0;transform:scale(.7);font-size:10px}.create-premium .cl-primary.cl-tile--on .create-check{opacity:1;transform:none}.create-premium .cl-primary.cl-tile--on .create-art{color:var(--accent)}.create-premium .cl-bar{margin:24px 0 0;padding:20px 0 0;border-radius:0;background:transparent}.create-premium .cl-continue{padding:12px 24px;border-radius:12px}.create-premium .cl-bulk{border-top:1px solid var(--border-glass);padding-top:20px}.create-premium .cl-bulk summary{list-style:none;display:flex;align-items:center;gap:8px}.create-premium .cl-bulk summary::before{content:'+';font-size:17px}.create-premium .cl-bulk[open] summary::before{content:'−'}.create-premium .cl-options{padding-top:24px}.create-premium .cl-options .cl-tile{background:var(--bg-card);border-color:var(--border-glass);min-height:84px}.create-premium form>.glass,.create-premium fieldset.glass{border:1px solid var(--border-glass);background:var(--bg-card);border-radius:18px}.create-premium fieldset label:has(input:checked){color:var(--accent);background:color-mix(in srgb,var(--accent) 6%,transparent);border-color:var(--accent)}.create-premium fieldset label{padding:12px;border:1px solid var(--border-glass);border-radius:12px}.create-premium input[type=radio]{accent-color:var(--accent)}.create-premium input:focus-visible,.create-premium select:focus-visible,.create-premium textarea:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@media(prefers-reduced-motion:no-preference){.create-premium .cl-primary{animation:create-arrive .35s ease-out both;transition:border-color .18s,background .18s}.create-premium .cl-primary:nth-child(2){animation-delay:40ms}.create-premium .cl-primary:nth-child(3){animation-delay:80ms}.create-premium .cl-primary:nth-child(4){animation-delay:120ms}.create-check{transition:opacity .18s,transform .18s}.create-art{transition:color .2s}.create-art .art-motion{transition:transform .25s ease}.cl-primary:hover .art-motion,.cl-primary:focus-visible .art-motion{transform:translateX(4px)}.cl-primary[data-art=biolink]:hover .art-motion,.cl-primary[data-art=biolink]:focus-visible .art-motion{transform:translateY(-3px)}.cl-primary[data-art=business]:hover .art-motion,.cl-primary[data-art=business]:focus-visible .art-motion{transform:translateY(3px)}.cl-primary[data-art=more]:hover .art-motion,.cl-primary[data-art=more]:focus-visible .art-motion{transform:rotate(8deg);transform-origin:70px 35px}.create-premium .cl-continue i{transition:transform .18s}.create-premium .cl-continue:hover i{transform:translateX(3px)}.create-premium form>.glass{animation:create-arrive .3s ease-out both}@keyframes create-arrive{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}}
@media(max-width:480px){.create-premium .cl-primary{padding:16px;min-height:180px}.create-premium .cl-primary strong{font-size:15px}.create-art{width:96px;height:62px}.create-premium .cl-primary-grid{gap:10px}}
